    { const char * tb_v324 = "TB_API volatile unsigned short *const tb_vga = (volatile unsigned short *)0xB8000;\n"; *(const char * *)tb_grow(v_lines) = tb_v324; }
    { const char * tb_v325 = "TB_API int tb_vrow = 0, tb_vcol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v325; }
    { const char * tb_v326 = "TB_API unsigned char tb_vcolor = 0x0A;   // светло-зелёный на чёрном\n"; *(const char * *)tb_grow(v_lines) = tb_v326; }
    { const char * tb_v327 = "TB_API void tb_vga_put(unsigned char ch) {\n"; *(const char * *)tb_grow(v_lines) = tb_v327; }
