    { const char * tb_v1167 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1167; }
    { const char * tb_v1168 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v1168; }
    { const char * tb_v1169 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v1169; }
    { const char * tb_v1170 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1170; }
    { const char * tb_v1171 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1171; }
    { const char * tb_v1172 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1172; }
