    { const char * tb_v1179 = "    exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1179; }
    { const char * tb_v1180 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1180; }
    { const char * tb_v1181 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1181; }
    { const char * tb_v1182 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1182; }
    { const char * tb_v1183 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1183; }
    { const char * tb_v1184 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1184; }
    { const char * tb_v1185 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1185; }
    { const char * tb_v1186 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1186; }
    { const char * tb_v1187 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1187; }
    { const char * tb_v1188 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1188; }
    { const char * tb_v1189 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v1189; }
    { const char * tb_v1190 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1190; }
    { const char * tb_v1191 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v1191; }
    { const char * tb_v1192 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v1192; }
    { const char * tb_v1193 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v1193; }
    { const char * tb_v1194 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v1194; }
    { const char * tb_v1195 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v1195; }
    { const char * tb_v1196 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1196; }
    { const char * tb_v1197 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1197; }
    { const char * tb_v1198 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1198; }
    { const char * tb_v1199 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1199; }
    { const char * tb_v1200 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1200; }
    { const char * tb_v1201 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1201; }
    { const char * tb_v1202 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1202; }
    { const char * tb_v1203 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1203; }
    { const char * tb_v1204 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1204; }
    { const char * tb_v1205 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v1205; }
    { const char * tb_v1206 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1206; }
    { const char * tb_v1207 = "TB_API _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1207; }
    { const char * tb_v1208 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v1208; }
    { const char * tb_v1209 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1209; }
    { const char * tb_v1210 = "TB_API void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1210; }
    { const char * tb_v1211 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v1211; }
