    { const char * tb_v1214 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1214; }
    { const char * tb_v1215 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1215; }
