    { const char * tb_v1217 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v1217; }
    { const char * tb_v1218 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1218; }
    { const char * tb_v1219 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1219; }
    { const char * tb_v1220 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v1220; }
    { const char * tb_v1221 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1221; }
    { const char * tb_v1222 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v1222; }
    { const char * tb_v1223 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1223; }
    { const char * tb_v1224 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1224; }
    { const char * tb_v1225 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1225; }
    { const char * tb_v1226 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1226; }
    { const char * tb_v1227 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1227; }
    { const char * tb_v1228 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1228; }
    { const char * tb_v1229 = "TB_API void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1229; }
    { const char * tb_v1230 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v1230; }
    { const char * tb_v1231 = "    ss.ss_sp = malloc(65536); ss.ss_size = 65536; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1231; }
    { const char * tb_v1232 = "    if (ss.ss_sp) sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1232; }
    { const char * tb_v1233 = "    tb_main_sp = here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1233; }
    { const char * tb_v1234 = "    tb_stack_lim = lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1234; }
    { const char * tb_v1235 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1235; }
    { const char * tb_v1236 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v1236; }
    { const char * tb_v1237 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v1237; }
    { const char * tb_v1238 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1238; }
    { const char * tb_v1239 = "// короткое ожидание без сна (подсказка процессору)\n"; *(const char * *)tb_grow(v_lines) = tb_v1239; }
    { const char * tb_v1240 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1240; }
    { const char * tb_v1241 = "#define __builtin_ia32_pause_or_yield() __builtin_ia32_pause()\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
    { const char * tb_v1242 = "#elif defined(__aarch64__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1242; }
    { const char * tb_v1243 = "#define __builtin_ia32_pause_or_yield() __asm__ volatile(\"yield\")\n"; *(const char * *)tb_grow(v_lines) = tb_v1243; }
    { const char * tb_v1244 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1244; }
    { const char * tb_v1245 = "#define __builtin_ia32_pause_or_yield() ((void)0)\n"; *(const char * *)tb_grow(v_lines) = tb_v1245; }
    { const char * tb_v1246 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1246; }
    { const char * tb_v1247 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1247; }
    { const char * tb_v1248 = "TB_API void *tb_tramp_run(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1248; }
    { const char * tb_v1249 = "    tb_tramp t = *(tb_tramp *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1249; }
    { const char * tb_v1250 = "    free(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v1250; }
    { const char * tb_v1251 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1251; }
