    { const char * tb_v2396 = "// ---------- время и дата ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "TB_API long long tb_unix_time(void) { return (long long)time(0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "    localtime_r(&t, &tmv);\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
