    { const char * tb_v2614 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v2614; }
    { const char * tb_v2615 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2615; }
    { const char * tb_v2616 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2616; }
    { const char * tb_v2617 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v2617; }
    { const char * tb_v2618 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2618; }
    { const char * tb_v2619 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2619; }
