    { const char * tb_v2639 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2639; }
    { const char * tb_v2640 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2640; }
