    { const char * tb_v3189 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
