    { const char * tb_v3199 = "    if (nb == 1) *(volatile uint8_t *)p = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "    else if (nb == 2) *(volatile uint16_t *)p = (uint16_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
