    { const char * tb_v3235 = "    static const char *sig[9] = { 0, \"число не влезает в поле i8: от -128 до 127\", \"число не влезает в поле i16: от -32 768 до 32 767\", 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "        \"число не влезает в поле i32: от -2 147 483 648 до 2 147 483 647\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
    { const char * tb_v3237 = "    TB_TOUCH(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3237; }
    { const char * tb_v3238 = "    if (bn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3238; }
    { const char * tb_v3239 = "        if (x < 0 || (bn < 63 && (x >> bn))) tb_crash(line, \"число не влезает в поле bits: от 0 до 2 в степени N без единицы\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3239; }
    { const char * tb_v3240 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3240; }
    { const char * tb_v3241 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3241; }
