    { const char * tb_v3612 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
