    { const char * tb_v6035 = "    for (int s = 0; s < TB_GSLOTS; s++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
    { const char * tb_v6036 = "        if (tb_mtl.cbs[s]) { TB_MSG(void, tb_mtl.cbs[s], \"waitUntilCompleted\"); TB_MSG(void, tb_mtl.cbs[s], \"release\"); tb_mtl.cbs[s] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6036; }
