    { const char * tb_v6783 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6783; }
    { const char * tb_v6784 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v6784; }
    { const char * tb_v6785 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v6785; }
    { const char * tb_v6786 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v6786; }
    { const char * tb_v6787 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v6787; }
    { const char * tb_v6788 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v6788; }
    { const char * tb_v6789 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6789; }
    { const char * tb_v6790 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6790; }
    { const char * tb_v6791 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6791; }
    { const char * tb_v6792 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6792; }
    { const char * tb_v6793 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6793; }
    { const char * tb_v6794 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6794; }
    { const char * tb_v6795 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6795; }
    { const char * tb_v6796 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v6796; }
    { const char * tb_v6797 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v6797; }
    { const char * tb_v6798 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v6798; }
    { const char * tb_v6799 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6799; }
    { const char * tb_v6800 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6800; }
    { const char * tb_v6801 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6801; }
    { const char * tb_v6802 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v6802; }
    { const char * tb_v6803 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v6803; }
    { const char * tb_v6804 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6804; }
    { const char * tb_v6805 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6805; }
    { const char * tb_v6806 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6806; }
    { const char * tb_v6807 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6807; }
    { const char * tb_v6808 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6808; }
    { const char * tb_v6809 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6809; }
    { const char * tb_v6810 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6810; }
    { const char * tb_v6811 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6811; }
    { const char * tb_v6812 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6812; }
    { const char * tb_v6813 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6813; }
    { const char * tb_v6814 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6814; }
    { const char * tb_v6815 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
    { const char * tb_v6816 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
    { const char * tb_v6818 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
    { const char * tb_v6820 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6820; }
    { const char * tb_v6821 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6821; }
    { const char * tb_v6822 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6822; }
    { const char * tb_v6823 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6823; }
    { const char * tb_v6824 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6824; }
    { const char * tb_v6825 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6825; }
    { const char * tb_v6826 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v6826; }
    { const char * tb_v6827 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6827; }
    { const char * tb_v6828 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6828; }
    { const char * tb_v6829 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6829; }
    { const char * tb_v6830 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6830; }
    { const char * tb_v6831 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6831; }
    { const char * tb_v6832 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6832; }
    { const char * tb_v6833 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6833; }
    { const char * tb_v6834 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6834; }
    { const char * tb_v6835 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
    { const char * tb_v6837 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6837; }
    { const char * tb_v6838 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6838; }
    { const char * tb_v6839 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v6839; }
    { const char * tb_v6840 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v6840; }
    { const char * tb_v6841 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
    { const char * tb_v6843 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6843; }
    { const char * tb_v6844 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6844; }
    { const char * tb_v6845 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6845; }
    { const char * tb_v6846 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
    { const char * tb_v6847 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6847; }
    { const char * tb_v6848 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
    { const char * tb_v6851 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
