    { const char * tb_v6990 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
