    { const char * tb_v6997 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6997; }
    { const char * tb_v6998 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
