    { const char * tb_v7017 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7017; }
    { const char * tb_v7018 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v7018; }
    { const char * tb_v7019 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7019; }
