    { const char * tb_v7028 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v7028; }
    { const char * tb_v7029 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7029; }
    { const char * tb_v7030 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v7030; }
    { const char * tb_v7031 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v7031; }
    { const char * tb_v7032 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7032; }
