    { const char * tb_v7042 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7042; }
    { const char * tb_v7043 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v7043; }
    { const char * tb_v7044 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7044; }
