    { const char * tb_v7057 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7057; }
    { const char * tb_v7058 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7058; }
