    { const char * tb_v7251 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
