    { const char * tb_v7287 = "    // 1) каждый угол нужных треугольников (один раз): поворот, место в мире, взгляд камеры, экран\n"; *(const char * *)tb_grow(v_lines) = tb_v7287; }
    { const char * tb_v7288 = "    for (long long t = t0; t < t1; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7288; }
    { const char * tb_v7289 = "        long long k = m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7289; }
