    { const char * tb_v7294 = "        double wx = p[0] * ca + p[2] * sa + x - tb_cam[0], wy = p[1] + y - tb_cam[1], wz = -p[0] * sa + p[2] * ca + z - tb_cam[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
    { const char * tb_v7295 = "        v->cx = wx * tb_cam[3] + wy * tb_cam[4] + wz * tb_cam[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
