    { const char * tb_v7306 = "            if (v->near_ok) { v->rx = tb_rnd(v->sx); v->ry = tb_rnd(v->sy); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
