    { const char * tb_v7332 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7332; }
    { const char * tb_v7333 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7333; }
    { const char * tb_v7334 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7334; }
    { const char * tb_v7335 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7335; }
    { const char * tb_v7336 = "        double sx[4], sy[4], dd[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7336; }
    { const char * tb_v7337 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7337; }
    { const char * tb_v7338 = "            double iz = 1 / qz[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7338; }
    { const char * tb_v7339 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
