    { const char * tb_v7417 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7417; }
    { const char * tb_v7418 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v7418; }
    { const char * tb_v7419 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7419; }
    { const char * tb_v7420 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7420; }
    { const char * tb_v7421 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7421; }
    { const char * tb_v7422 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7422; }
    { const char * tb_v7423 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v7423; }
    { const char * tb_v7424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7424; }
    { const char * tb_v7425 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
    { const char * tb_v7426 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
    { const char * tb_v7428 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7428; }
    { const char * tb_v7429 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7429; }
    { const char * tb_v7430 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7430; }
    { const char * tb_v7431 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v7431; }
    { const char * tb_v7432 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7432; }
    { const char * tb_v7433 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v7433; }
    { const char * tb_v7434 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v7434; }
    { const char * tb_v7435 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7435; }
    { const char * tb_v7436 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7436; }
    { const char * tb_v7437 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7437; }
    { const char * tb_v7438 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7438; }
    { const char * tb_v7439 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7439; }
    { const char * tb_v7440 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7440; }
    { const char * tb_v7441 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7441; }
    { const char * tb_v7442 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v7442; }
    { const char * tb_v7443 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
    { const char * tb_v7444 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v7444; }
    { const char * tb_v7445 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v7445; }
    { const char * tb_v7446 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7446; }
    { const char * tb_v7447 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7447; }
    { const char * tb_v7448 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v7448; }
    { const char * tb_v7449 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v7449; }
    { const char * tb_v7450 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7450; }
    { const char * tb_v7451 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7451; }
    { const char * tb_v7452 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7452; }
    { const char * tb_v7453 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v7453; }
    { const char * tb_v7454 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7454; }
