    { const char * tb_v7474 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7474; }
    { const char * tb_v7475 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v7475; }
    { const char * tb_v7476 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7476; }
    { const char * tb_v7477 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7477; }
    { const char * tb_v7478 = "        for (int i = 0; i < 3; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7478; }
    { const char * tb_v7479 = "            if (tb_3ist[ti[i]] != gen) { tb_3ist[ti[i]] = gen; tb_m3_corner(go->rec.r, m->vi + 4 * ti[i], fq, tb_3i + 3 * ti[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7479; }
