    { const char * tb_v7485 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v7485; }
    { const char * tb_v7486 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v7486; }
    { const char * tb_v7487 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v7487; }
