    { const char * tb_v7630 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7630; }
    { const char * tb_v7631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7631; }
    { const char * tb_v7632 = "TB_API void tb_clipboard_set(const char *s) { tb_gfx_clip_set(s ? s : \"\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7632; }
    { const char * tb_v7633 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v7633; }
    { const char * tb_v7634 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7634; }
    { const char * tb_v7635 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v7635; }
    { const char * tb_v7636 = "    for (int i = 0; i < 8; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7636; }
