    { const char * tb_v7642 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7642; }
    { const char * tb_v7643 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7643; }
    { const char * tb_v7644 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v7644; }
    { const char * tb_v7645 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v7645; }
    { const char * tb_v7646 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v7646; }
    { const char * tb_v7647 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v7647; }
    { const char * tb_v7648 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7648; }
    { const char * tb_v7649 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v7649; }
    { const char * tb_v7650 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v7650; }
    { const char * tb_v7651 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v7651; }
    { const char * tb_v7652 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v7652; }
    { const char * tb_v7653 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v7653; }
    { const char * tb_v7654 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v7654; }
    { const char * tb_v7655 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v7655; }
    { const char * tb_v7656 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v7656; }
    { const char * tb_v7657 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v7657; }
    { const char * tb_v7658 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v7658; }
    { const char * tb_v7659 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7659; }
    { const char * tb_v7660 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7660; }
    { const char * tb_v7661 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v7661; }
    { const char * tb_v7662 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v7662; }
    { const char * tb_v7663 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v7663; }
    { const char * tb_v7664 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7664; }
    { const char * tb_v7665 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v7665; }
    { const char * tb_v7666 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7666; }
    { const char * tb_v7667 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7667; }
    { const char * tb_v7668 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v7668; }
    { const char * tb_v7669 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7669; }
    { const char * tb_v7670 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v7670; }
    { const char * tb_v7671 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v7671; }
    { const char * tb_v7672 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7672; }
    { const char * tb_v7673 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v7673; }
    { const char * tb_v7674 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7674; }
    { const char * tb_v7675 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v7675; }
    { const char * tb_v7676 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7676; }
    { const char * tb_v7677 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7677; }
    { const char * tb_v7678 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7678; }
    { const char * tb_v7679 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v7679; }
    { const char * tb_v7680 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7680; }
    { const char * tb_v7681 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7681; }
    { const char * tb_v7682 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7682; }
    { const char * tb_v7683 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7683; }
    { const char * tb_v7684 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7684; }
    { const char * tb_v7685 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7685; }
    { const char * tb_v7686 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7686; }
    { const char * tb_v7687 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v7687; }
    { const char * tb_v7688 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7688; }
    { const char * tb_v7689 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v7689; }
    { const char * tb_v7690 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7690; }
    { const char * tb_v7691 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7691; }
    { const char * tb_v7692 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v7692; }
    { const char * tb_v7693 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7693; }
    { const char * tb_v7694 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7694; }
    { const char * tb_v7695 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7695; }
    { const char * tb_v7696 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7696; }
    { const char * tb_v7697 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7697; }
    { const char * tb_v7698 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7698; }
    { const char * tb_v7699 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v7699; }
    { const char * tb_v7700 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7700; }
    { const char * tb_v7701 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7701; }
    { const char * tb_v7702 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v7702; }
    { const char * tb_v7703 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7703; }
    { const char * tb_v7704 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7704; }
    { const char * tb_v7705 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7705; }
    { const char * tb_v7706 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7706; }
    { const char * tb_v7707 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7707; }
    { const char * tb_v7708 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v7708; }
    { const char * tb_v7709 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7709; }
    { const char * tb_v7710 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7710; }
    { const char * tb_v7711 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7711; }
    { const char * tb_v7712 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7712; }
    { const char * tb_v7713 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7713; }
    { const char * tb_v7714 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7714; }
    { const char * tb_v7715 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7715; }
    { const char * tb_v7716 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7716; }
    { const char * tb_v7717 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v7717; }
    { const char * tb_v7718 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v7718; }
    { const char * tb_v7719 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v7719; }
    { const char * tb_v7720 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7720; }
    { const char * tb_v7721 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7721; }
    { const char * tb_v7722 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v7722; }
    { const char * tb_v7723 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7723; }
    { const char * tb_v7724 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7724; }
    { const char * tb_v7725 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7725; }
    { const char * tb_v7726 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7726; }
    { const char * tb_v7727 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v7727; }
    { const char * tb_v7728 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7728; }
    { const char * tb_v7729 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7729; }
    { const char * tb_v7730 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7730; }
    { const char * tb_v7731 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v7731; }
    { const char * tb_v7732 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7732; }
    { const char * tb_v7733 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7733; }
    { const char * tb_v7734 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7734; }
    { const char * tb_v7735 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v7735; }
    { const char * tb_v7736 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v7736; }
    { const char * tb_v7737 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7737; }
    { const char * tb_v7738 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7738; }
    { const char * tb_v7739 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7739; }
    { const char * tb_v7740 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7740; }
    { const char * tb_v7741 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7741; }
    { const char * tb_v7742 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v7742; }
    { const char * tb_v7743 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7743; }
    { const char * tb_v7744 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v7744; }
    { const char * tb_v7745 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v7745; }
    { const char * tb_v7746 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7746; }
    { const char * tb_v7747 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7747; }
    { const char * tb_v7748 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7748; }
    { const char * tb_v7749 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7749; }
    { const char * tb_v7750 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7750; }
    { const char * tb_v7751 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7751; }
    { const char * tb_v7752 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7752; }
    { const char * tb_v7753 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v7753; }
    { const char * tb_v7754 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7754; }
    { const char * tb_v7755 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7755; }
    { const char * tb_v7756 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7756; }
    { const char * tb_v7757 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7757; }
    { const char * tb_v7758 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7758; }
    { const char * tb_v7759 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7759; }
    { const char * tb_v7760 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7760; }
    { const char * tb_v7761 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7761; }
    { const char * tb_v7762 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7762; }
    { const char * tb_v7763 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7763; }
