    { const char * tb_v8080 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v8080; }
    { const char * tb_v8081 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8081; }
    { const char * tb_v8082 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8082; }
    { const char * tb_v8083 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8083; }
    { const char * tb_v8084 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8084; }
    { const char * tb_v8085 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v8085; }
    { const char * tb_v8086 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8086; }
    { const char * tb_v8087 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v8087; }
    { const char * tb_v8088 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8088; }
    { const char * tb_v8089 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8089; }
    { const char * tb_v8090 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8090; }
    { const char * tb_v8091 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8091; }
    { const char * tb_v8092 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8092; }
    { const char * tb_v8093 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8093; }
    { const char * tb_v8094 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8094; }
    { const char * tb_v8095 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8095; }
